from lxml import objectify

from taf.gnb.oam.ne3s.ws.components.connection.messages import (
    AttachmentType, Default, NotificationType,
    extract_xml_value)
from taf.gnb.oam.ne3s.ws.components.connection.notification_pool import NotificationPool


class NotificationFactory(object):
    @classmethod
    def from_parts(cls, filter_name, msg_group,
                   soap, attachment=None, *other_parts):
        attachment_part, soap_part = cls._create_parts(attachment, soap)

        queue_id = getattr(soap_part, 'queue_id', None)
        factories = NotificationPool.get_notification_groups(queue_id)

        matching_notifications = []
        for factory in factories:
            for notification in factory.matching_notifications(filter_name, msg_group, soap_part, attachment_part):
                matching_notifications.append(notification)

        if matching_notifications:
            return matching_notifications
        else:
            return [Default(filter_name, msg_group, soap_part, attachment_part)]

    @classmethod
    def _create_parts(cls, attachment, soap):
        try:
            soap_content = soap.content
        except AttributeError:
            soap_content = soap

        soap_xml = objectify.fromstring(soap_content)
        soap_type = cls._extract_soap_type(soap_xml)
        content_type = extract_xml_value(soap_xml, "contentType")

        soap_part = NotificationType.SoapMapping[soap_type](soap_xml)

        attachment_content = attachment.content if attachment else None
        if content_type:
            attachment_part = AttachmentType.ContentTypeMapping[content_type](
                attachment_content)
        else:
            if attachment_content is not None:
                raise ValueError("Attachment part is supplied, "
                                 "but content type was not given.")
            attachment_part = None
        return attachment_part, soap_part

    @classmethod
    def _extract_soap_type(cls, soap):
        return soap.Body.getchildren()[0].tag.split('}')[-1]
